import React from 'react';
import { SolutionResponse } from '../../types';

interface ResultsDisplayProps {
    result: SolutionResponse;
}

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {
    // Форматирование для инженерного вывода
    const formatNum = (val: number) => {
        if (val === 0) return "0.0";
        // Если число слишком маленькое (невязка), используем экспоненциальный вид
        if (Math.abs(val) < 1e-6) return val.toExponential(4);
        return val.toLocaleString('ru-RU', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 10
        });
    };

    return (
        <div className="space-y-8 font-sans">
            {/* Верхняя панель характеристик */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-px bg-slate-200 border">
                {[
                    { label: 'Определитель', value: formatNum(result.determinant) },
                    { label: 'Норма матрицы', value: formatNum(result.matrixNorm) },
                    { label: 'Итераций', value: result.iterations },
                    { label: 'Статус сходимости', value: result.diagonalDominance ? 'ДОСТИГНУТО' : 'НЕ ВЫПОЛНЕНО' }
                ].map((item, i) => (
                    <div key={i} className="bg-white p-4">
                        <div className="text-[10px] font-bold uppercase text-slate-400 mb-1">{item.label}</div>
                        <div className="font-mono font-bold text-slate-800">{item.value}</div>
                    </div>
                ))}
            </div>

            {/* Вектор решения и невязки */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div>
                    <h3 className="text-xs font-bold uppercase text-slate-500 mb-3 tracking-widest">Вектор решения (X)</h3>
                    <div className="border border-slate-900 overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-slate-900 text-white text-[10px] uppercase">
                            <tr>
                                <th className="px-3 py-1 text-left">i</th>
                                <th className="px-3 py-1 text-right">x[i]</th>
                            </tr>
                            </thead>
                            <tbody className="font-mono divide-y">
                            {result.solution.map((val, idx) => (
                                <tr key={idx} className="hover:bg-slate-50">
                                    <td className="px-3 py-1.5 text-slate-400 border-r w-12">{idx + 1}</td>
                                    <td className="px-3 py-1.5 text-right">{formatNum(val)}</td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                <div>
                    <h3 className="text-xs font-bold uppercase text-slate-500 mb-3 tracking-widest">Вектор невязки (R)</h3>
                    <div className="border border-slate-200 overflow-hidden">
                        <table className="w-full text-sm text-slate-500">
                            <thead className="bg-slate-100 text-[10px] uppercase">
                            <tr>
                                <th className="px-3 py-1 text-left">i</th>
                                <th className="px-3 py-1 text-right">Ax - b</th>
                            </tr>
                            </thead>
                            <tbody className="font-mono divide-y divide-slate-100">
                            {result.residual.map((val, idx) => (
                                <tr key={idx}>
                                    <td className="px-3 py-1.5 border-r w-12">{idx + 1}</td>
                                    <td className="px-3 py-1.5 text-right text-xs">{formatNum(val)}</td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Итоговое сообщение */}
            <div className="p-4 border-l-4 border-slate-900 bg-slate-50">
                <p className="text-xs leading-relaxed">
                    <span className="font-bold uppercase mr-2">Status:</span>
                    {result.message}
                </p>
            </div>
        </div>
    );
};
